/* ============================================================
   Book 3 · Lesson 14 · Reading a real LULC change report critically
   Data: Ou Char (Battambang), 2021 → 2025, from the author's GEE LULC Toolkit report.
   Usage: <div class="sim" data-sim="rs-lulc-report"></div>
   ============================================================ */
(function () {
  "use strict";
  window.EXTRA_SIMS = window.EXTRA_SIMS || {};
  const KM = "០១២៣៤៥៦៧៨៩";
  const kh = (n) => String(n).replace(/[0-9]/g, (d) => KM[d]);
  const fmtN = (n, dec = 0) => kh(Number(n).toLocaleString("en-US", { minimumFractionDigits: dec, maximumFractionDigits: dec }).replace(/,/g, " ").replace(".", ","));
  const MAPS = {"y2021": "data:image/png;base64,", "y2025": "data:image/png;base64,", "change": "data:image/png;base64,"};
  const C = [["ទឹក", "Water", "#0000ff"], ["រុក្ខជាតិ", "Vegetation", "#228b22"], ["សំណង់", "Built-up", "#ff0000"], ["ដីទទេ", "Bare soil", "#d2b48c"],
    ["ដីសើម", "Wetland", "#26c6da"], ["ដីដាំដុះ", "Cropland", "#ffa500"], ["វាលស្មៅ", "Grassland", "#7fff00"]];
  // change matrix (ha), rows = 2021, columns = 2025 ("·" in the report = 0)
  const M = [[10, 2, 0, 0, 0, 1, 2], [1, 194, 14, 0, 0, 7, 12], [0, 31, 179, 3, 0, 3, 10], [0, 0, 5, 5, 0, 1, 7],
    [0, 0, 0, 0, 0, 0, 0], [0, 34, 3, 0, 0, 227, 43], [0, 57, 11, 4, 0, 53, 100]];
  const ROW = [14, 227, 226, 18, 0, 307, 226], COL = [11, 318, 212, 13, 0, 292, 173], TOT = 1020;
  const ACC = [[100, 11.1, 20], [65.4, 73.1, 69], [83.1, 81.2, 82.2], [46, 42.6, 44.2], [0, 0, 0], [62.4, 86, 72.3], [64.3, 41.2, 50.2]];   // producer, user, F1
  const OA = 69.6, KAPPA = 0.598;
  window.EXTRA_SIMS["rs-lulc-report"] = (el) => {
    el.innerHTML = `<div class="sim-title">ករណីសិក្សា៖ អានរបាយការណ៍ការផ្លាស់ប្ដូរ LULC អូរចារ ២០២១ → ២០២៥</div>
      <div class="sim-controls"><span class="sim-seg lr-t">
        <button type="button" data-v="map" class="on">ផែនទី</button><button type="button" data-v="mx">តារាងផ្លាស់ប្ដូរ</button>
        <button type="button" data-v="gl">សុទ្ធ និងប្ដូរកន្លែង</button><button type="button" data-v="acc">ភាពត្រឹមត្រូវ</button><button type="button" data-v="err">កំហុសកកកុញ</button></span></div>
      <div class="lr-body" style="margin-top:8px"></div><div class="sim-out"></div>`;
    const q = (s) => el.querySelector(s), body = q(".lr-body"), out = q(".sim-out");
    const sw = (c) => `<i style="display:inline-block;width:12px;height:12px;background:${c};border:1px solid #0003;vertical-align:-1px;margin-right:4px"></i>`;
    const legend = `<div style="display:flex;flex-wrap:wrap;gap:4px 14px;font-size:.68rem;margin-top:6px">${C.filter((c, i) => i !== 4).map((c) => `<span>${sw(c[2])}${c[0]}</span>`).join("")}</div>`;
    let tab = "map", sel = -1;
    const views = {
      map: () => { body.innerHTML = `<div class="sim-controls"><span class="sim-seg lr-m"><button type="button" data-v="y2021" class="on">២០២១</button><button type="button" data-v="y2025">២០២៥</button><button type="button" data-v="change">តែក្រឡាដែលប្ដូរ (ថ្នាក់ថ្មី)</button></span></div>
          <img class="lr-img" alt="" src="${MAPS.y2021}" style="width:100%;max-width:560px;display:block;margin:6px auto;image-rendering:pixelated">${legend}`;
        el.querySelectorAll(".lr-m button").forEach((b) => (b.onclick = () => { el.querySelectorAll(".lr-m button").forEach((x) => x.classList.toggle("on", x === b)); q(".lr-img").src = MAPS[b.dataset.v]; }));
        out.innerHTML = `ផ្ទៃសរុប ${fmtN(TOT)} ហ.ត · ក្រឡា ៣០ ម · ផ្លាស់ប្ដូរ ${fmtN(305)} ហ.ត (${fmtN(29.8, 1)}%)។ សង្កេតផែនទី «តែក្រឡាដែលប្ដូរ»៖ ការផ្លាស់ប្ដូរពិតតែងជាដុំៗ (ការសាងសង់ ការឈូសឆាយ)។ ចំណុចតូចៗរាយប៉ាយគ្រប់កន្លែង (salt-and-pepper) ច្រើនតែជាកំហុសចាត់ថ្នាក់។`; },
      mx: () => { const mx = Math.max(...M.flat());
        let h = `<div style="overflow-x:auto"><table style="border-collapse:collapse;font-size:.66rem;margin:auto"><tr><th style="padding:3px 6px">២០២១ ↓ · ២០២៥ →</th>${C.map((c) => `<th style="padding:3px 4px">${sw(c[2])}${c[0]}</th>`).join("")}<th>Σ</th></tr>`;
        M.forEach((r, i) => { h += `<tr data-r="${i}" style="cursor:pointer;${sel === i ? "outline:2px solid #ff9800" : ""}"><th style="text-align:left;padding:3px 6px">${sw(C[i][2])}${C[i][0]}</th>` +
          r.map((v, j) => { const a = v / mx, diag = i === j; return `<td style="text-align:right;padding:4px 6px;border:1px solid #e0e0e0;background:${diag ? `rgba(120,144,156,${0.15 + a * 0.6})` : `rgba(229,57,53,${a * 0.9})`};${a > 0.5 ? "color:#fff" : ""}">${v ? fmtN(v) : "·"}</td>`; }).join("") + `<th>${fmtN(ROW[i])}</th></tr>`; });
        h += `<tr><th>Σ</th>${COL.map((v) => `<th style="padding:3px 6px;text-align:right">${fmtN(v)}</th>`).join("")}<th>${fmtN(TOT)}</th></tr></table></div>`;
        body.innerHTML = h;
        body.querySelectorAll("tr[data-r]").forEach((tr) => (tr.onclick = () => { sel = +tr.dataset.r === sel ? -1 : +tr.dataset.r; views.mx(); }));
        if (sel >= 0) { const r = M[sel], kept = r[sel], lost = ROW[sel] - kept, gained = COL[sel] - M[sel][sel];
          const to = r.map((v, j) => [v, j]).filter(([v, j]) => j !== sel && v > 0).sort((a, b) => b[0] - a[0]).map(([v, j]) => `${C[j][0]} ${fmtN(v)}`).join(" · ");
          out.innerHTML = `<b>${C[sel][0]}</b>៖ នៅដដែល ${fmtN(kept)} ហ.ត · បាត់ ${fmtN(lost)} ហ.ត (${to || "—"}) · ទទួលបាន ${fmtN(gained)} ហ.ត ពីថ្នាក់ផ្សេង។` +
            (sel === 2 ? ` <b style="color:#c62828">សំណង់ → រុក្ខជាតិ ៣១ ហ.ត ក្នុង ៤ ឆ្នាំ៖ ការរុះរើអគារ ហើយដាំដើមឈើ កម្រកើតឡើងណាស់។ ទំនងជាដើមឈើក្នុងទីធ្លា ឬកំហុសចាត់ថ្នាក់។</b>` : "");
        } else out.innerHTML = `ជួរដេក = ថ្នាក់ឆ្នាំ ២០២១ · ជួរឈរ = ថ្នាក់ឆ្នាំ ២០២៥។ អង្កត់ទ្រូង (ប្រផេះ) = មិនប្ដូរ ${fmtN(715)} ហ.ត · ក្រៅអង្កត់ទ្រូង (ក្រហម) = ការផ្លាស់ប្ដូរ ${fmtN(305)} ហ.ត។ ចុចលើជួរដេកមួយ ដើម្បីមើលថ្នាក់នោះទៅណា។`; },
      gl: () => { const rows = C.map((c, i) => { const g = COL[i] - M[i][i], l = ROW[i] - M[i][i]; return { i, g, l, net: g - l, swap: 2 * Math.min(g, l) }; }).filter((r) => r.i !== 4);
        const mx = Math.max(...rows.map((r) => Math.max(r.g, r.l))), sc = 150 / mx;
        let s = `<svg viewBox="0 0 620 ${rows.length * 34 + 40}" style="width:100%;height:auto;font-family:inherit"><line x1="310" y1="20" x2="310" y2="${rows.length * 34 + 22}" stroke="#555"/>
          <text x="300" y="14" text-anchor="end" font-size="11" fill="#c62828">← បាត់ (loss)</text><text x="320" y="14" font-size="11" fill="#2e7d32">ទទួលបាន (gain) →</text>`;
        rows.forEach((r, k) => { const y = 24 + k * 34;
          s += `<rect x="${310 - r.l * sc}" y="${y}" width="${r.l * sc}" height="12" fill="#ef9a9a"/><rect x="310" y="${y}" width="${r.g * sc}" height="12" fill="#a5d6a7"/>
            <rect x="${Math.min(310, 310 + r.net * sc)}" y="${y + 14}" width="${Math.abs(r.net) * sc}" height="7" fill="${r.net >= 0 ? "#2e7d32" : "#c62828"}"/>
            <text x="6" y="${y + 11}" font-size="11">${C[r.i][0]}</text><text x="614" y="${y + 11}" font-size="10" text-anchor="end">សុទ្ធ ${r.net >= 0 ? "+" : "−"}${fmtN(Math.abs(r.net))} · ប្ដូរកន្លែង ${fmtN(r.swap)}</text>`; });
        body.innerHTML = s + `</svg>`;
        const gross = 305, net = rows.reduce((a, r) => a + Math.abs(r.net), 0) / 2, swap = gross - net;
        out.innerHTML = `ការផ្លាស់ប្ដូរសរុប (gross) ${fmtN(gross)} ហ.ត = <b>សុទ្ធ (net) ${fmtN(net)} ហ.ត</b> + <b>ប្ដូរកន្លែង (swap) ${fmtN(swap)} ហ.ត (${fmtN((swap / gross) * 100)}%)</b>។ ` +
          `Swap មានន័យថាថ្នាក់មួយបាត់នៅកន្លែងខ្លះ ហើយកើតនៅកន្លែងផ្សេង។ នៅទីនេះ swap ធំបំផុតរវាងវាលស្មៅ ដីដាំដុះ និងរុក្ខជាតិ ដែលជាថ្នាក់ដែលម៉ូដែលច្រឡំគ្នាច្រើនបំផុត (ភាពត្រឹមត្រូវ ៤១–៧៣%)។ ដូច្នេះ swap ភាគច្រើនអាចជាកំហុស មិនមែនការផ្លាស់ប្ដូរពិតទេ។`; },
      acc: () => { let h = `<table style="border-collapse:collapse;font-size:.7rem;margin:auto"><tr><th style="padding:4px 8px;text-align:left">ថ្នាក់</th><th style="padding:4px 8px">Producer's</th><th style="padding:4px 8px">User's</th><th style="padding:4px 8px">F1</th><th style="padding:4px 8px;text-align:left">អានយ៉ាងណា</th></tr>`;
        const note = ["ចាប់បានទឹកពិតទាំងអស់ ប៉ុន្តែ ៨៩% នៃក្រឡាដែលហៅថា «ទឹក» មិនមែនទឹកទេ៖ ប៉ាន់ធំ", "មធ្យម", "ល្អបំផុត", "ច្រឡំជាមួយសំណង់ និងស្មៅ", "គ្មានក្នុងតំបន់៖ គួរដកចេញ", "ល្អ (User's ខ្ពស់)", "User's ទាប៖ ៥៩% នៃ «ស្មៅ» ជាថ្នាក់ផ្សេង"];
        ACC.forEach((a, i) => { const bad = (v) => (v < 50 ? "color:#c62828;font-weight:700" : v < 70 ? "color:#ef6c00" : "color:#2e7d32");
          h += `<tr><td style="padding:4px 8px;border-top:1px solid #e0e0e0">${sw(C[i][2])}${C[i][0]}</td>${a.map((v) => `<td style="text-align:right;padding:4px 8px;border-top:1px solid #e0e0e0;${bad(v)}">${fmtN(v, 1)}%</td>`).join("")}<td style="padding:4px 8px;border-top:1px solid #e0e0e0">${note[i]}</td></tr>`; });
        body.innerHTML = h + `</table>`;
        out.innerHTML = `Overall accuracy ${fmtN(OA, 1)}% · Kappa ${fmtN(KAPPA, 3)} · គំរូត្រួតពិនិត្យ ១ ៨៤៣ ក្រឡា លើប្លុក ២ គម ដែលមិនបានប្រើបណ្ដុះបណ្ដាល។ <b>ប្រយ័ត្ន</b>៖ នេះជាការស៊ីគ្នាជាមួយ ESA WorldCover (ប្រភពស្លាកដែលប្រើបណ្ដុះបណ្ដាល ហើយខ្លួនវាត្រឹមត្រូវប្រហែល ៧៥%) មិនមែនការផ្ទៀងផ្ទាត់នៅទីវាលឯករាជ្យទេ។`; },
      err: () => { body.innerHTML = `<div class="sim-controls"><label>ភាពត្រឹមត្រូវផែនទី ២០២១ <input class="lr-p1" type="range" min="60" max="99" value="70"> <b class="lr-p1v"></b></label>
          <label>ផែនទី ២០២៥ <input class="lr-p2" type="range" min="60" max="99" value="70"> <b class="lr-p2v"></b></label>
          <label>កំហុសដូចគ្នាទាំងពីរឆ្នាំ <input class="lr-c" type="range" min="0" max="90" value="50"> <b class="lr-cv"></b></label></div><div class="lr-bar"></div>`;
        const upd = () => { const p1 = +q(".lr-p1").value / 100, p2 = +q(".lr-p2").value / 100, c = +q(".lr-c").value / 100;
          q(".lr-p1v").textContent = fmtN(p1 * 100) + "%"; q(".lr-p2v").textContent = fmtN(p2 * 100) + "%"; q(".lr-cv").textContent = fmtN(c * 100) + "%";
          const spur = (1 - c) * (1 - p1 * p2) * 100, obs = 29.8;
          q(".lr-bar").innerHTML = `<svg viewBox="0 0 620 110" style="width:100%;height:auto;font-family:inherit">
            <text x="0" y="16" font-size="12">ការផ្លាស់ប្ដូរដែលរបាយការណ៍រាយការណ៍</text><rect x="0" y="24" width="${obs * 6}" height="18" fill="#e53935"/><text x="${obs * 6 + 6}" y="38" font-size="12">${fmtN(obs, 1)}%</text>
            <text x="0" y="68" font-size="12">ការផ្លាស់ប្ដូរក្លែងក្លាយដែលកំហុសអាចបង្កើត (ប៉ាន់ស្មាន)</text><rect x="0" y="76" width="${Math.min(100, spur) * 6}" height="18" fill="#9e9e9e"/><text x="${Math.min(100, spur) * 6 + 6}" y="90" font-size="12">${fmtN(spur, 1)}%</text></svg>`;
          out.innerHTML = `ម៉ូដែលសាមញ្ញ៖ ក្រឡាដែលមិនប្ដូរពិត ត្រូវបានចាត់ថ្នាក់ត្រឹមត្រូវទាំងពីរឆ្នាំ ក្នុងប្រូបាប ${fmtN(p1 * p2 * 100, 1)}%។ ក្នុងករណីផ្សេង ផែនទីអាចបង្ហាញ «ការផ្លាស់ប្ដូរ» ដែលមិនពិត លើកលែងតែកំហុសទាំងពីរឆ្នាំដូចគ្នា (ម៉ូដែលតែមួយ រូបភាពស្រដៀងគ្នា)។ ` +
            (spur >= obs * 0.7 ? `<b style="color:#c62828">កំហុសអាចពន្យល់ការផ្លាស់ប្ដូរភាគច្រើនដែលរាយការណ៍។</b> ត្រូវផ្ទៀងផ្ទាត់ក្រឡាប្ដូរដោយគំរូឯករាជ្យ មុនសន្និដ្ឋាន។` : `ការផ្លាស់ប្ដូរដែលរាយការណ៍ ធំជាងកំហុសដែលអាចកើតគួរសម៖ ទំនុកចិត្តខ្ពស់ជាង។`) +
            `<br><span class="sim-hint">ម៉ូដែលនេះសាមញ្ញសម្រាប់បង្រៀន៖ ការប៉ាន់ផ្ទៃត្រឹមត្រូវ ប្រើគំរូយោងតាមស្រទាប់ (stratified) និងចន្លោះទំនុកចិត្ត (Olofsson et al., 2014)។</span>`; };
        body.querySelectorAll("input").forEach((i) => (i.oninput = upd)); upd(); },
    };
    el.querySelectorAll(".lr-t button").forEach((b) => (b.onclick = () => { el.querySelectorAll(".lr-t button").forEach((x) => x.classList.toggle("on", x === b)); tab = b.dataset.v; views[tab](); }));
    views.map();
  };
})();
